for l in locations:
    for t in range(T):
        local_demand_premium = demand_curve["SKU_Premium"][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales["SKU_Premium", l, t, r] for r in range(1, shelf_life["SKU_Premium"] + 1))
            - sub[l, t] + lost["SKU_Premium", l, t] == local_demand_premium,
            name=f"demand_premium_{l}_{t}"
        )

for l in locations:
    for t in range(T):
        local_demand_short = demand_curve["SKU_ShortLife"][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales["SKU_ShortLife", l, t, r] for r in range(1, shelf_life["SKU_ShortLife"] + 1))
            + lost["SKU_ShortLife", l, t] == local_demand_short,
            name=f"demand_short_{l}_{t}"
        )

for l in locations:
    for t in range(T):
        end_inv = gp.quicksum(
            cold_usage[p] * (I[p, l, t, r] - sales[p, l, t, r])
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        m.addConstr(end_inv <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

obj = gp.LinExpr()

for p in products:
    for t in range(T):
        obj += cost_purchasing[p] * Q[p, t]

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_waste[p] * W[p, l, t]

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_lost_sales[p] * lost[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost including:
- Purchasing costs (production costs)
- Inventory holding costs (charged on end-of-period inventory for items with r >= 2)
- Waste costs (items that expire)
- Lost sales costs (demand not met)

**Decisions to make:**
- Q[p,t]: Production quantity for product p in period t
- sales[p,l,t,r]: Sales of product p at location l in period t from inventory with r periods remaining
- I[p,l,t,r]: Inventory of product p at location l at start of period t with r periods remaining
- W[p,l,t]: Waste of product p at location l in period t

**Constraints:**
1. Production capacity: Q[p,t] <= production_cap[p,t]
2. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
3. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
4. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
5. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
6. Demand satisfaction: Total sales + substitution <= demand (with substitution from Basic to Premium)
7. Cold storage capacity: sum over products of (cold_usage[p] * total_inventory[p,l,t]) <= cold_capacity[l]
8. Non-negativity

**Substitution:** SKU_Basic can substitute for SKU_Premium demand (Basic's demand served by Premium)

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P = {SKU_Basic, SKU_Premium, SKU_ShortLife}: products
- L = {DC1, DC2, DC3, DC4, DC5}: locations
- T = {0, 1, ..., 19}: periods
- R[p] = {1, 2, ..., shelf_life[p]}: remaining life for product p

**Parameters:**
- demand[p,t]: demand curve for product p in period t
- demand_share[l]: fraction of production going to location l
- shelf_life[p]: shelf life of product p
- production_cap[p,t]: production capacity
- cold_capacity[l]: cold storage capacity at location l
- cold_usage[p]: cold storage usage per unit of product p
- c_purchase[p], c_hold[p], c_waste[p], c_lost[p]: costs

**Decision Variables:**
- Q[p,t] >= 0: CONTINUOUS - production quantity (can be fractional)
- I[p,l,t,r] >= 0: CONTINUOUS - inventory
- sales[p,l,t,r] >= 0: CONTINUOUS - sales from specific age bucket
- W[p,l,t] >= 0: CONTINUOUS - waste
- lost_sales[p,l,t] >= 0: CONTINUOUS - lost sales
- sub[l,t] >= 0: CONTINUOUS - substitution (Basic serving Premium demand)

**Constraints:**
1. Production capacity: Q[p,t] <= production_cap[p,t]
2. Fresh inflow: I[p,l,t,SL[p]] = Q[p,t] * demand_share[l]
3. Aging (for t < T-1): I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL[p]-1
4. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
5. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
6. Demand for Premium: sum_r(sales[Premium,l,t,r]) + sub[l,t] + lost_sales[Premium,l,t] = demand[Premium,t] * demand_share[l]
7. Demand for Basic: sum_r(sales[Basic,l,t,r]) - sub[l,t] + lost_sales[Basic,l,t] = demand[Basic,t] * demand_share[l]
8. Demand for ShortLife: sum_r(sales[ShortLife,l,t,r]) + lost_sales[ShortLife,l,t] = demand[ShortLife,t] * demand_share[l]
9. Cold storage: sum_p(cold_usage[p] * sum_r(I[p,l,t,r])) <= cold_capacity[l]
10. Initial inventory (t=0): I[p,l,0,r] = 0 for r < SL[p]

**Objective:**
Minimize: sum of purchasing + holding + waste + lost_sales costs

