for (p1, p2) in sub_edges:
    for l in locations:
        for t in range(T):
            sub[p1, p2, l, t] = m.addVar(lb=0, name=f"sub_{p1}_{p2}_{l}_{t}")

m.update()

# Constraints

# 1. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

# 2. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T - 1):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1], name=f"aging_{p}_{l}_{t}_{r}")

# 3. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

# 4. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

# 5. Demand satisfaction with substitution
# Total sales of p + lost sales + incoming substitution = demand + outgoing substitution
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            total_sales_p = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))
            demand_p_l_t = demand_curve[p][t] * demand_share[l]

            incoming_sub = gp.quicksum(sub[p1, p, l, t] for (p1, p2) in sub_edges if p2 == p and (p1, p, l, t) in sub)
            outgoing_sub = gp.quicksum(sub[p, p2, l, t] for (p1, p2) in sub_edges if p1 == p and (p, p2, l, t) in sub)

            m.addConstr(total_sales_p + L[p, l, t] + incoming_sub == demand_p_l_t + outgoing_sub, name=f"demand_{p}_{l}_{t}")

# 6. Substitution limit: outgoing substitution <= total sales
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            total_sales_p = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))
            outgoing_sub = gp.quicksum(sub[p, p2, l, t] for (p1, p2) in sub_edges if p1 == p and (p, p2, l, t) in sub)
            m.addConstr(outgoing_sub <= total_sales_p, name=f"sub_limit_{p}_{l}_{t}")

# 7. Cold capacity
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1)) for p in products) <= cold_capacity[l],
            name=f"cold_cap_{l}_{t}"
        )

# 8. Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# 9. Initial inventory for periods where we need to set non-fresh buckets to 0 at t=0
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += c_purch[p] * Q[p, t]

# Holding cost: charged on (I[p,l,t,r] - sales[p,l,t,r]) for r >= 2
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += c_hold[p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += c_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += c_lost[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

