import gurobipy as gp
from gurobipy import GRB
import json

json_str = '''
{
  "name": "retail_f3_storage_bottleneck_v1",
  "description": "Standard seasonal retail scenario.",
  "periods": 20,
  "products": ["SKU_Basic", "SKU_Premium", "SKU_ShortLife"],
  "locations": ["DC1", "DC2", "DC3", "DC4", "DC5"],
  "shelf_life": {"SKU_Basic": 10, "SKU_Premium": 8, "SKU_ShortLife": 4},
  "lead_time": {"SKU_Basic": 0, "SKU_Premium": 0, "SKU_ShortLife": 0},
  "cold_capacity": {"DC1": 1055.8079522800297, "DC2": 1018.6134333265579, "DC3": 859.9214861012979, "DC4": 790.3183063284633, "DC5": 713.9196544245406},
  "cold_usage": {"SKU_Basic": 1.0, "SKU_Premium": 3.0, "SKU_ShortLife": 1.2},
  "production_cap": {"SKU_Basic": [800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800], "SKU_Premium": [400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400], "SKU_ShortLife": [500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500]},
  "labor_cap": {"DC1": [99999.0]*20, "DC2": [99999.0]*20, "DC3": [99999.0]*20, "DC4": [99999.0]*20, "DC5": [99999.0]*20},
  "labor_usage": {"SKU_Basic": 0.0, "SKU_Premium": 0.0, "SKU_ShortLife": 0.0},
  "return_rate": {"SKU_Basic": 0.0, "SKU_Premium": 0.0, "SKU_ShortLife": 0.0},
  "demand_curve": {"SKU_Basic": [302,301,366,379,386,628,658,784,1008,1187,1451,1335,938,805,610,600,410,346,342,302], "SKU_Premium": [143,149,160,192,235,252,393,405,609,578,724,532,580,473,325,296,211,178,161,169], "SKU_ShortLife": [131,114,112,156,189,202,317,338,382,529,565,483,446,410,299,186,154,152,136,122]},
  "demand_share": {"DC1": 0.25, "DC2": 0.2, "DC3": 0.2, "DC4": 0.2, "DC5": 0.15},
  "costs": {"lost_sales": {"SKU_Basic": 50.0, "SKU_Premium": 80.0, "SKU_ShortLife": 40.0}, "inventory": {"SKU_Basic": 1.0, "SKU_Premium": 1.5, "SKU_ShortLife": 1.0}, "waste": {"SKU_Basic": 2.0, "SKU_Premium": 3.0, "SKU_ShortLife": 2.0}, "fixed_order": 0.0, "transshipment": 0.5, "purchasing": {"SKU_Basic": 10.0, "SKU_Premium": 20.0, "SKU_ShortLife": 15.0}},
  "constraints": {"moq": 0, "pack_size": 1, "budget_per_period": null, "waste_limit_pct": null},
  "network": {"sub_edges": [["SKU_Basic", "SKU_Premium"]], "trans_edges": []}
}
'''
data = json.loads(json_str)

products = data["products"]
locations = data["locations"]
T = data["periods"]
shelf_life = data["shelf_life"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
cost_purchasing = data["costs"]["purchasing"]
cost_inventory = data["costs"]["inventory"]
cost_waste = data["costs"]["waste"]
cost_lost_sales = data["costs"]["lost_sales"]
sub_edges = data["network"]["sub_edges"]

m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales from own product
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

# Substitution sales: Premium serving Basic demand
sub_sales = {}
for l in locations:
    for t in range(T):
        SL_prem = shelf_life["SKU_Premium"]
        for r in range(1, SL_prem + 1):
            sub_sales["SKU_Premium", l, t, r] = m.addVar(lb=0, name=f"sub_sales_Premium_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(T):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

m.update()

# Constraints

# Initial inventory = 0
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0)

# Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t])

# Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l])

# Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] - sub_sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                if p == "SKU_Premium":
                    m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1] - sub_sales[p, l, t, r + 1])
                else:
                    m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1])

# Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1] - sub_sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            if p == "SKU_Premium":
                m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1] - sub_sales[p, l, t, 1])
            else:
                m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# Sales availability: sales[p,l,t,r] + sub_sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                if p == "SKU_Premium":
                    m.addConstr(sales[p, l, t, r] + sub_sales[p, l, t, r] <= I[p, l, t, r])
                else:
                    m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])

# Demand satisfaction
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            local_demand = demand_curve[p][t] * demand_share[l]
            if p == "SKU_Basic":
                # Basic demand can be met by Basic sales + Premium substitution
                SL_prem = shelf_life["SKU_Premium"]
                m.addConstr(
                    gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) +
                    gp.quicksum(sub_sales["SKU_Premium", l, t, r] for r in range(1, SL_prem + 1)) +
                    L[p, l, t] == local_demand
                )
            else:
                m.addConstr(
                    gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) +
                    L[p, l, t] == local_demand
                )

# Storage capacity constraint
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * I[p, l, t, r]
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l]
        )

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += cost_purchasing[p] * Q[p, t]

# Inventory holding cost (on end-of-period inventory for r >= 2)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                if p == "SKU_Premium":
                    obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r] - sub_sales[p, l, t, r])
                else:
                    obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_lost_sales[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)
m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

