                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

for l in locations:
    for t in range(T):
        for r in range(1, SL_prem + 1):
            m.addConstr(sub_sales[l, t, r] <= I["SKU_Premium", l, t, r] - sales["SKU_Premium", l, t, r], name=f"sub_avail_{l}_{t}_{r}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            local_demand = demand_curve[p][t] * demand_share[l]
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))
            if p == "SKU_Basic":
                total_sub = gp.quicksum(sub_sales[l, t, r] for r in range(1, SL_prem + 1))
                m.addConstr(total_sales + total_sub + L[p, l, t] == local_demand, name=f"demand_{p}_{l}_{t}")
            else:
                m.addConstr(total_sales + L[p, l, t] == local_demand, name=f"demand_{p}_{l}_{t}")

for l in locations:
    for t in range(T):
        total_inv = gp.quicksum(cold_usage[p] * I[p, l, t, r] for p in products for r in range(1, shelf_life[p] + 1))
        m.addConstr(total_inv <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

obj = gp.LinExpr()
for p in products:
    for t in range(T):
        obj += c_purch[p] * Q[p, t]

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += c_inv[p] * (I[p, l, t, r] - sales[p, l, t, r])

for p in products:
    for l in locations:
        for t in range(T):
            obj += c_waste[p] * W[p, l, t]

for p in products:
    for l in locations:
        for t in range(T):
            obj += c_lost[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)
m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost consisting of:
- Purchasing costs (for production)
- Inventory holding costs (on end-of-period inventory, excluding expiring items)
- Waste costs (items that expire unsold)
- Lost sales costs (unmet demand)

**Decisions to make:**
- Q[p,t]: Production quantity for product p in period t
- I[p,l,t,r]: Inventory at start of period t at location l with r periods remaining
- sales[p,l,t,r]: Sales from inventory with r periods remaining
- W[p,l,t]: Waste at location l for product p in period t
- lost_sales[p,l,t]: Lost sales for product p at location l in period t

**Constraints:**
1. Production capacity: Q[p,t] ≤ production_cap[p,t]
2. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
3. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
4. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
5. Sales availability: sales[p,l,t,r] ≤ I[p,l,t,r]
6. Demand satisfaction: sum of sales + substitution sales ≤ demand
7. Lost sales: lost_sales[p,l,t] = demand[p,l,t] - total_sales[p,l,t]
8. Substitution: SKU_Basic can substitute for SKU_Premium
9. Non-negativity

**Parameters given:**
- 3 products, 5 locations, 20 periods
- Shelf lives: Basic=10, Premium=8, ShortLife=4
- Production caps, demand curves, demand shares
- Various costs

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P = {SKU_Basic, SKU_Premium, SKU_ShortLife}
- L = {DC1, DC2, DC3, DC4, DC5}
- T = {0, 1, ..., 19}
- R[p] = {1, 2, ..., shelf_life[p]} (remaining life periods)

**Parameters:**
- SL[p]: shelf life of product p
- demand[p,t]: total demand for product p in period t
- share[l]: demand share for location l
- cap[p,t]: production capacity for product p in period t
- c_purch[p], c_hold[p], c_waste[p], c_lost[p]: costs

**Decision Variables (all CONTINUOUS since fractional units are acceptable):**
- Q[p,t] ≥ 0: production quantity
- I[p,l,t,r] ≥ 0: inventory at start of period t with r remaining
- sales[p,l,t,r] ≥ 0: sales from inventory with r remaining
- sub_sales[p,l,t] ≥ 0: substitution sales (Basic substituting for Premium)
- W[p,l,t] ≥ 0: waste
- lost[p,l,t] ≥ 0: lost sales

**Constraints:**
1. Q[p,t] ≤ cap[p,t]
2. I[p,l,t,SL[p]] = Q[p,t] * share[l] for all p,l,t
3. I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL[p]-1
4. W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
5. sales[p,l,t,r] ≤ I[p,l,t,r]
6. Σ_r sales[p,l,t,r] + sub_received[p,l,t] + lost[p,l,t] = demand[p,l,t] * share[l] / Σshare
7. sub_sales[Basic,l,t] = sub_received[Premium,l,t]
8. Σ_r sales[Basic,l,t,r] + sub_sales[Basic,l,t] ≤ available Basic inventory

**Objective:**
Minimize Σ (purchasing + holding + waste + lost_sales costs)

## STEP 3: GENERATE GUROBI CODE

```python
import gurobipy as gp
from gurobipy import GRB

# Sets
products = ["SKU_Basic", "SKU_Premium", "SKU_ShortLife"]
locations = ["DC1", "DC2", "DC3", "DC4", "DC5"]
T = range(data["num_periods"])

# Parameters
shelf_life = {
    "SKU_Basic": data["shelf_life_sku_basic"],
    "SKU_Premium": data["shelf_life_sku_premium"],
    "SKU_ShortLife": data["shelf_life_sku_shortlife"]
}

production_cap = {
    "SKU_Basic": data["production_cap_sku_basic"],
    "SKU_Premium": data["production_cap_sku_premium"],
    "SKU_ShortLife": data["production_cap_sku_shortlife"]
}

demand_curve = {
    "SKU_Basic": data["demand_curve_sku_basic"],
    "SKU_Premium": data["demand_curve_sku_premium"],
    "SKU_ShortLife": data["demand_curve_sku_shortlife"]
}

demand_share = {
    "DC1": data["demand_share_dc1"],
    "DC2": data["demand_share_dc2"],
    "DC3": data["demand_share_dc3"],
    "DC4": data["demand_share_dc4"],
    "DC5": data["demand_share_dc5"]
}

c_purch = {
    "SKU_Basic": data["purchasing_cost_sku_basic"],
    "SKU_Premium": data["purchasing_cost_sku_premium"],
    "SKU_ShortLife": data["purchasing_cost_sku_shortlife"]
}

c_hold = {
    "SKU_Basic": data["inventory_cost_sku_basic"],
    "SKU_Premium": data["inventory_cost_sku_premium"],
    "SKU_ShortLife": data["inventory_cost_sku_shortlife"]
}

c_waste = {
    "SKU_Basic": data["waste_cost_sku_basic"],
    "SKU_Premium": data["waste_cost_sku_premium"],
    "SKU_ShortLife": data["waste_cost_sku_shortlife"]
}

c_lost = {
    "SKU_Basic": data["lost_sales_cost_sku_basic"],
    "SKU_Premium": data["lost_sales_cost_sku_premium"],
    "SKU_ShortLife": data["lost_sales_cost_sku_shortlife"]
}

# Model
m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision Variables
Q = {}
for p in products:
    for t in T:
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(data["num_periods"] + 1):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}
for p in products:
    for l in locations:
        for t in T:
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

lost = {}
for p in products:
    for l in locations:
        for t in T:
            lost[p, l, t] = m.addVar(lb=0, name=f"lost_{p}_{l}_{t}")

# Substitution: SKU_Basic can substitute for SKU_Premium
sub_sales = {}
for l in locations:
    for t in T:
        sub_sales[l, t] = m.addVar(lb=0, name=f"sub_{l}_{t}")

# Constraints

# 1. Production capacity
for p in products:
    for t in T:
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"cap_{p}_{t}")

# 2. Initial inventory is zero (t=0)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_{p}_{l}_{r}")

# 3. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

# 4. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1],
                           name=f"aging_{p}_{l}_{t}_{r}")

# 5. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in T:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1],
                       name=f"waste_{p}_{l}_{t}")

# 6. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r],
                           name=f"avail_{p}_{l}_{t}_{r}")

# 7. Demand satisfaction with substitution
# SKU_Basic can substitute for SKU_Premium
# For SKU_Basic: total_sales_basic = sum(sales[Basic]) + sub_sales (used to substitute Premium)
# For SKU_Premium: demand = sum(sales[Premium]) + sub_received + lost
# For SKU_ShortLife: demand = sum(sales[ShortLife]) + lost

for l in locations:
    for t in T:
        # SKU_Premium demand can be met by Premium sales + substitution from Basic
        demand_premium = demand_curve["SKU_Premium"][t] * demand_share[l]
        SL_prem = shelf_life["SKU_Premium"]
        m.addConstr(
            gp.quicksum(sales["SKU_Premium", l, t, r] for r in range(1, SL_prem + 1)) + sub_sales[l, t] + lost["SKU_Premium", l, t] == demand_premium,
            name=f"demand_Premium_{l}_{t}"
        )

        # SKU_Basic: total sales + substitution must not exceed available
        demand_basic = demand_curve["SKU_Basic"][t] * demand_share[l]
        SL_basic = shelf_life["SKU_Basic"]
        total_basic_sales = gp.quicksum(sales["SKU_Basic", l, t, r] for r in range(1, SL_basic + 1))
        m.addConstr(
            total_basic_sales + lost["SKU_Basic", l, t] == demand_basic + sub_sales[l, t],
            name=f"demand_Basic_{l}_{t}"
        )

        # SKU_ShortLife: no substitution
        demand_short = demand_curve["SKU_ShortLife"][t] * demand_share[l]
        SL_short = shelf_life["SKU_ShortLife"]
        m.addConstr(
            gp.quicksum(sales["SKU_ShortLife", l, t, r] for r in range(1, SL_short + 1)) + lost["SKU_ShortLife", l, t] == demand_short,
            name=f"demand_Short_{l}_{t}"
        )

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in T:
        obj += c_purch[p] * Q[p, t]

# Holding cost: charged on (I[p,l,t,r] - sales[p,l,t,r]) for r >= 2
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(2, SL + 1):
                obj += c_hold[p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in T:
            obj += c_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in T:
            obj += c_lost[p] * lost[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
