    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):  # Need T+1 for aging constraints
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales by remaining life
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

lost = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(T):
            lost[p, l, t] = m.addVar(lb=0, name=f"lost_{p}_{l}_{t}")

sub = {}  # Substitution: Basic substitutes for Premium
for l in locations:
    for t in range(T):
        sub[l, t] = m.addVar(lb=0, name=f"sub_{l}_{t}")

m.update()

# Constraints

# Initial inventory = 0
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0)

# Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t])

# Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l])

# Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1])

# Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])

# Demand satisfaction with substitution
for l in locations:
    for t in range(T):
        # Premium: can be satisfied by Premium sales + substitution from Basic
        SL_prem = shelf_life["SKU_Premium"]
        demand_prem = demand_curve["SKU_Premium"][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales["SKU_Premium", l, t, r] for r in range(1, SL_prem + 1))
            + sub[l, t] + lost["SKU_Premium", l, t] == demand_prem
        )

        # Basic: sales minus what's used for substitution
        SL_basic = shelf_life["SKU_Basic"]
        demand_basic = demand_curve["SKU_Basic"][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales["SKU_Basic", l, t, r] for r in range(1, SL_basic + 1))
            - sub[l, t] + lost["SKU_Basic", l, t] == demand_basic
        )

        # ShortLife: no substitution
        SL_short = shelf_life["SKU_ShortLife"]
        demand_short = demand_curve["SKU_ShortLife"][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales["SKU_ShortLife", l, t, r] for r in range(1, SL_short + 1))
            + lost["SKU_ShortLife", l, t] == demand_short
        )

# Cold storage capacity
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * I[p, l, t, r]
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l]
        )

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += costs["purchasing"][p] * Q[p, t]

# Inventory holding cost (on end-of-period inventory, r >= 2)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += costs["inventory"][p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["waste"][p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["lost_sales"][p] * lost[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost consisting of:
- Purchasing costs
- Inventory holding costs
- Waste costs (expired products)
- Lost sales costs

**Decisions to make:**
- Q[p,t]: Total production/ordering quantity for product p in period t
- I[p,l,t,r]: Inventory of product p at location l at start of period t with r periods remaining life
- sales[p,l,t,r]: Sales of product p at location l in period t from inventory with r remaining life
- W[p,l,t]: Waste of product p at location l in period t
- L[p,l,t]: Lost sales of product p at location l in period t

**Constraints:**
1. Production capacity limits
2. Cold storage capacity at each location (highly unbalanced)
3. Inventory flow/aging equations with FIFO
4. Sales cannot exceed inventory
5. Demand satisfaction (sales + lost sales = demand)
6. Non-negativity

**Key features:**
- Perishable products with shelf life tracking
- No transshipment between locations
- Demand is distributed to locations via demand_share
- Substitution: SKU_Basic can substitute for SKU_Premium

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P: Products
- L: Locations
- T: Time periods {0, 1, ..., num_periods-1}
- R[p]: Remaining life values {1, 2, ..., shelf_life[p]}

**Parameters:**
- demand[p,t]: Total demand for product p in period t
- demand_share[l]: Fraction of demand at location l
- shelf_life[p]: Shelf life of product p
- cold_capacity[l]: Storage capacity at location l
- cold_usage[p]: Storage space per unit of product p
- production_cap[p,t]: Production capacity
- cost_purchasing[p], cost_inventory[p], cost_waste[p], cost_lost_sales[p]

**Decision Variables (all CONTINUOUS since fractional units are acceptable):**
- Q[p,t] ≥ 0: Production quantity
- I[p,l,t,r] ≥ 0: Inventory at start of period t with r remaining life
- sales[p,l,t,r] ≥ 0: Sales from inventory with r remaining life
- W[p,l,t] ≥ 0: Waste
- L[p,l,t] ≥ 0: Lost sales
- sub[l,t] ≥ 0: Substitution of Basic for Premium at location l, period t

**Constraints:**

1. **Fresh inflow (Eq 1):** I[p,l,t,SL[p]] = Q[p,t] * demand_share[l]

2. **Aging (Eq 2):** I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL[p]-1

3. **Waste (Eq 3):** W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]

4. **Sales availability (Eq 4):** sales[p,l,t,r] ≤ I[p,l,t,r]

5. **Demand satisfaction:** 
   - For Premium: sum_r(sales[Premium,l,t,r]) + sub[l,t] + L[Premium,l,t] = demand[Premium,t] * demand_share[l]
   - For Basic: sum_r(sales[Basic,l,t,r]) - sub[l,t] + L[Basic,l,t] = demand[Basic,t] * demand_share[l]
   - For ShortLife: sum_r(sales[ShortLife,l,t,r]) + L[ShortLife,l,t] = demand[ShortLife,t] * demand_share[l]

6. **Cold capacity:** sum_p sum_r (cold_usage[p] * I[p,l,t,r]) ≤ cold_capacity[l]

7. **Production capacity:** Q[p,t] ≤ production_cap[p,t]

8. **Initial inventory:** I[p,l,0,r] = 0 for all r < SL[p]

**Objective:** Minimize
- sum_{p,t} cost_purchasing[p] * Q[p,t]
- + sum_{p,l,t,r≥2} cost_inventory[p] * (I[p,l,t,r] - sales[p,l,t,r])
- + sum_{p,l,t} cost_waste[p] * W[p,l,t]
- + sum_{p,l,t} cost_lost_sales[p] * L[p,l,t]

