    "DC1": 0.25,
    "DC2": 0.2,
    "DC3": 0.2,
    "DC4": 0.2,
    "DC5": 0.15
  },
  "costs": {
    "lost_sales": {
      "SKU_Basic": 50.0,
      "SKU_Premium": 80.0,
      "SKU_ShortLife": 40.0
    },
    "inventory": {
      "SKU_Basic": 1.0,
      "SKU_Premium": 1.5,
      "SKU_ShortLife": 1.0
    },
    "waste": {
      "SKU_Basic": 2.0,
      "SKU_Premium": 3.0,
      "SKU_ShortLife": 2.0
    },
    "fixed_order": 0.0,
    "transshipment": 0.5,
    "purchasing": {
      "SKU_Basic": 10.0,
      "SKU_Premium": 20.0,
      "SKU_ShortLife": 15.0
    }
  },
  "constraints": {
    "moq": 0,
    "pack_size": 1,
    "budget_per_period": null,
    "waste_limit_pct": null
  },
  "network": {
    "sub_edges": [
      ["SKU_Basic", "SKU_Premium"]
    ],
    "trans_edges": []
  }
}
"""

data = json.loads(json_data)

# Extract data
products = data["products"]
locations = data["locations"]
num_periods = data["periods"]
shelf_life = data["shelf_life"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
cost_purchasing = data["costs"]["purchasing"]
cost_inventory = data["costs"]["inventory"]
cost_waste = data["costs"]["waste"]
cost_lost_sales = data["costs"]["lost_sales"]
sub_edges = data["network"]["sub_edges"]

# Compute local demand
demand = {}
for p in products:
    for l in locations:
        for t in range(num_periods):
            demand[p, l, t] = demand_curve[p][t] * demand_share[l]

# Create model
m = gp.Model("retail_optimization")
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production quantity
for p in products:
    for t in range(num_periods):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory by remaining life
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales by remaining life
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(num_periods):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

lost_sales_var = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(num_periods):
            lost_sales_var[p, l, t] = m.addVar(lb=0, name=f"lost_{p}_{l}_{t}")

# Substitution variables (Basic can substitute for Premium)
sub_sales = {}
for (p_from, p_to) in sub_edges:
    for l in locations:
        for t in range(num_periods):
            sub_sales[p_from, p_to, l, t] = m.addVar(lb=0, name=f"sub_{p_from}_{p_to}_{l}_{t}")

# Constraints

# 1. Production capacity
for p in products:
    for t in range(num_periods):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# 2. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

# 3. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods - 1):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1],
                           name=f"aging_{p}_{l}_{t}_{r}")

# 4. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(num_periods):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

# 5. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

# 6. Demand satisfaction with substitution
# For products that can receive substitution (Premium)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods):
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))
            # Add substitution received
            sub_received = gp.quicksum(sub_sales[p_from, p, l, t] 
                                       for (p_from, p_to) in sub_edges if p_to == p)
            m.addConstr(total_sales + sub_received + lost_sales_var[p, l, t] == demand[p, l, t],
                       name=f"demand_{p}_{l}_{t}")

# 7. Substitution limited by available inventory after own sales
# For Basic: total sales + substitution given <= total inventory
for (p_from, p_to) in sub_edges:
    SL_from = shelf_life[p_from]
    for l in locations:
        for t in range(num_periods):
            total_inv = gp.quicksum(I[p_from, l, t, r] for r in range(1, SL_from + 1))
            total_own_sales = gp.quicksum(sales[p_from, l, t, r] for r in range(1, SL_from + 1))
            m.addConstr(total_own_sales + sub_sales[p_from, p_to, l, t] <= total_inv,
                       name=f"sub_limit_{p_from}_{p_to}_{l}_{t}")

# 8. Cold storage capacity
for l in locations:
    for t in range(num_periods):
        total_storage = gp.quicksum(
            cold_usage[p] * I[p, l, t, r]
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        m.addConstr(total_storage <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

# 9. Initial inventory at t=0 for r < SL must be 0 (no pre-existing inventory)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# Objective: minimize total cost
purchasing_cost = gp.quicksum(cost_purchasing[p] * Q[p, t] 
                              for p in products for t in range(num_periods))

# Holding cost on end-of-period inventory (I - sales) for r >= 2
holding_cost = gp.quicksum(
    cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products
    for l in locations
    for t in range(num_periods)
    for r in range(2, shelf_life[p] + 1)
)

waste_cost = gp.quicksum(cost_waste[p] * W[p, l, t]
                         for p in products for l in locations for t in range(num_periods))

lost_sales_cost = gp.quicksum(cost_lost_sales[p] * lost_sales_var[p, l, t]
                              for p in products for l in locations for t in range(num_periods))

m.setObjective(purchasing_cost + holding_cost + waste_cost + lost_sales_cost, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost consisting of:
- Purchasing costs for production
- Inventory holding costs (on end-of-period inventory, excluding expiring items)
- Waste costs (items that expire unsold)
- Lost sales costs (unmet demand)

**Decisions to make:**
- Q[p,t]: Production quantity for product p in period t
- I[p,l,t,r]: Inventory at location l, start of period t, with r periods remaining life
- sales[p,l,t,r]: Sales from inventory with r periods remaining
- W[p,l,t]: Waste at location l in period t
- lost_sales[p,l,t]: Unmet demand

**Constraints:**
1. Production capacity limits
2. Cold storage capacity at each location
3. Inventory flow/aging equations (FIFO)
4. Sales limited by available inventory
5. Demand satisfaction (sales + lost_sales = demand)
6. Substitution: SKU_Basic can substitute for SKU_Premium

**Parameters:** Products, locations, periods, shelf life, demand curves, costs, capacities, etc.

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets and Indices:**
- P: Products {SKU_Basic, SKU_Premium, SKU_ShortLife}
- L: Locations {DC1, DC2, DC3, DC4, DC5}
- T: Periods {0, 1, ..., 19}
- R_p: Remaining life for product p {1, 2, ..., shelf_life[p]}

**Parameters:**
- SL[p]: shelf_life for product p
- demand[p,t]: total demand for product p in period t
- share[l]: demand share for location l
- prod_cap[p,t]: production capacity
- cold_cap[l]: cold storage capacity
- cold_use[p]: cold storage usage per unit
- c_purch[p], c_inv[p], c_waste[p], c_lost[p]: costs

**Decision Variables (all CONTINUOUS since fractional units are acceptable):**
- Q[p,t] ≥ 0: Production quantity
- I[p,l,t,r] ≥ 0: Inventory at start of period t with r remaining life
- sales[p,l,t,r] ≥ 0: Sales from inventory with r remaining
- W[p,l,t] ≥ 0: Waste
- lost[p,l,t] ≥ 0: Lost sales
- sub[l,t] ≥ 0: Substitution (SKU_Basic substituting for SKU_Premium)

**Constraints:**

1. **Fresh inflow (Eq 1):** I[p,l,t,SL[p]] = Q[p,t] * share[l]

2. **Aging (Eq 2):** I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL[p]-1

3. **Waste (Eq 3):** W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]

4. **Sales availability (Eq 4):** sales[p,l,t,r] ≤ I[p,l,t,r]

5. **Demand satisfaction:** 
   - For SKU_Premium: Σ_r sales[Premium,l,t,r] + sub[l,t] + lost[Premium,l,t] = demand[Premium,t] * share[l]
   - For SKU_Basic: Σ_r sales[Basic,l,t,r] - sub[l,t] + lost[Basic,l,t] = demand[Basic,t] * share[l]
   - For SKU_ShortLife: Σ_r sales[ShortLife,l,t,r] + lost[ShortLife,l,t] = demand[ShortLife,t] * share[l]

6. **Production capacity:** Q[p,t] ≤ prod_cap[p,t]

7. **Cold storage capacity:** Σ_p Σ_r cold_use[p] * I[p,l,t,r] ≤ cold_cap[l]

8. **Initial inventory:** I[p,l,0,r] = 0 for all r < SL[p]

**Objective:** Minimize
- Σ_p,t c_purch[p] * Q[p,t]
- + Σ_p,l,t,r (r≥2) c_inv[p] * (I[p,l,t,r] - sales[p,l,t,r])
- + Σ_p,l,t c_waste[p] * W[p,l,t]
- + Σ_p,l,t c_lost[p] * lost[p,l,t]

