    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1], name=f"aging_{p}_{l}_{t}_{r}")

for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1)) for p in products) <= cold_capacity[l],
            name=f"cold_cap_{l}_{t}"
        )

for l in locations:
    for t in range(T):
        p = "SKU_Basic"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + sub[l, t] + lost[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

for l in locations:
    for t in range(T):
        p = "SKU_Premium"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + sub[l, t] + lost[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

for l in locations:
    for t in range(T):
        p = "SKU_ShortLife"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + lost[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

obj = gp.LinExpr()

for p in products:
    for t in range(T):
        obj += costs["purchasing"][p] * Q[p, t]

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += costs["inventory"][p] * (I[p, l, t, r] - sales[p, l, t, r])

for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["waste"][p] * W[p, l, t]

for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["lost_sales"][p] * lost[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
