    "SKU_ShortLife": data["cost_inventory_sku_shortlife"]
}

cost_waste = {
    "SKU_Basic": data["cost_waste_sku_basic"],
    "SKU_Premium": data["cost_waste_sku_premium"],
    "SKU_ShortLife": data["cost_waste_sku_shortlife"]
}

cost_lost_sales = {
    "SKU_Basic": data["cost_lost_sales_sku_basic"],
    "SKU_Premium": data["cost_lost_sales_sku_premium"],
    "SKU_ShortLife": data["cost_lost_sales_sku_shortlife"]
}

m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

Q = {}
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}
for p in products:
    for l in locations:
        for t in range(T):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1)) for p in products) <= cold_capacity[l],
            name=f"storage_cap_{l}_{t}"
        )

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_inflow_{p}_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1], name=f"aging_{p}_{l}_{t}_{r}")

for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            demand_plt = demand_curve[p][t] * demand_share[l]
            m.addConstr(
                gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + L[p, l, t] == demand_plt,
                name=f"demand_sat_{p}_{l}_{t}"
            )

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

obj = gp.LinExpr()

for p in products:
    for t in range(T):
        obj += cost_purchasing[p] * Q[p, t]

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_waste[p] * W[p, l, t]

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_lost_sales[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
