products = data["products"]
locations = data["locations"]
T = data["periods"]
shelf_life = data["shelf_life"]
demand_share = data["demand_share"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
demand_curve = data["demand_curve"]
costs = data["costs"]

m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):  # Need t+1 for aging
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

lost_sales = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(T):
            lost_sales[p, l, t] = m.addVar(lb=0, name=f"lost_{p}_{l}_{t}")

# Substitution: Basic can substitute Premium
sub = {}
for l in locations:
    for t in range(T):
        sub[l, t] = m.addVar(lb=0, name=f"sub_{l}_{t}")

m.update()

# Constraints

# Initial inventory is zero at t=0
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_{p}_{l}_{r}")

# Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

# Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1],
                            name=f"aging_{p}_{l}_{t}_{r}")

# Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

# Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

# Demand satisfaction with substitution
# For SKU_Premium: sales + sub + lost_sales = demand
# For SKU_Basic: sales - sub + lost_sales = demand (sub comes from Basic inventory)
# For SKU_ShortLife: sales + lost_sales = demand
for l in locations:
    for t in range(T):
        # SKU_Basic demand (minus substitution used for Premium)
        p = "SKU_Basic"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) - sub[l, t] + lost_sales[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

        # SKU_Premium demand (can be satisfied by substitution from Basic)
        p = "SKU_Premium"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + sub[l, t] + lost_sales[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

        # SKU_ShortLife demand
        p = "SKU_ShortLife"
        SL = shelf_life[p]
        local_demand = demand_curve[p][t] * demand_share[l]
        m.addConstr(
            gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + lost_sales[p, l, t] == local_demand,
            name=f"demand_{p}_{l}_{t}"
        )

# Storage capacity constraint (on inventory AFTER sales, i.e., end of period)
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * (I[p, l, t, r] - sales[p, l, t, r])
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l],
            name=f"capacity_{l}_{t}"
        )

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += costs["purchasing"][p] * Q[p, t]

# Inventory holding cost (on end-of-period inventory, excluding r=1)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += costs["inventory"][p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["waste"][p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += costs["lost_sales"][p] * lost_sales[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
