    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t])

# (1) Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l])

# (2) Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1])

# (3) Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1])

# (4) Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r])

# Storage capacity: sum over products of (cold_usage[p] * total_inventory[p,l,t]) <= cold_capacity[l]
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * I[p, l, t, r]
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l]
        )

# Demand satisfaction with substitution
# For SKU_Basic: total_sales + lost_sales = demand (can give away to substitute Premium)
# For SKU_Premium: total_sales + lost_sales + sub_in = demand
# For SKU_ShortLife: total_sales + lost_sales = demand
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            demand_plt = demand_curve[p][t] * demand_share[l]
            total_sales_p = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))

            sub_out_p = gp.quicksum(sub[p, p_to, l, t] for (p_from, p_to) in sub_edges if p_from == p and (p, p_to, l, t) in sub)
            sub_in_p = gp.quicksum(sub[p_from, p, l, t] for (p_from, p_to) in sub_edges if p_to == p and (p_from, p, l, t) in sub)

            m.addConstr(total_sales_p + lost_sales[p, l, t] + sub_in_p == demand_plt + sub_out_p)

# Substitution limited by available sales of the substitute product
# sub[p_from, p_to, l, t] uses inventory from p_from
for edge in sub_edges:
    p_from, p_to = edge[0], edge[1]
    SL_from = shelf_life[p_from]
    for l in locations:
        for t in range(T):
            total_sales_from = gp.quicksum(sales[p_from, l, t, r] for r in range(1, SL_from + 1))
            demand_from = demand_curve[p_from][t] * demand_share[l]
            m.addConstr(sub[p_from, p_to, l, t] <= total_sales_from - (demand_from - lost_sales[p_from, l, t]))

# Objective: minimize total cost
purchasing_cost = gp.quicksum(cost_purchasing[p] * Q[p, t] for p in products for t in range(T))

holding_cost = gp.quicksum(
    cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products
    for l in locations
    for t in range(T)
    for r in range(2, shelf_life[p] + 1)
)

waste_cost = gp.quicksum(cost_waste[p] * W[p, l, t] for p in products for l in locations for t in range(T))

lost_sales_cost = gp.quicksum(cost_lost_sales[p] * lost_sales[p, l, t] for p in products for l in locations for t in range(T))

m.setObjective(purchasing_cost + holding_cost + waste_cost + lost_sales_cost, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

