cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
costs = data["costs"]
trans_edges = data["network"]["trans_edges"]
sub_edges = data["network"]["sub_edges"]

hub = "DC1"
spokes = [l for l in locations if l != hub]

m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

Q = {}
for p in products:
    for t in range(periods):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in range(periods + 1):
            for r in range(1, sl + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in range(periods):
            for r in range(1, sl + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

T = {}
for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in range(periods):
            for r in range(1, sl + 1):
                T[p, l, t, r] = m.addVar(lb=0, name=f"T_{p}_{l}_{t}_{r}")

W = {}
for p in products:
    for l in locations:
        for t in range(periods):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}
for p in products:
    for l in locations:
        for t in range(periods):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

sub = {}
for (p_from, p_to) in sub_edges:
    for l in locations:
        for t in range(periods):
            sub[p_from, p_to, l, t] = m.addVar(lb=0, name=f"sub_{p_from}_{p_to}_{l}_{t}")

for p in products:
    for t in range(periods):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

for p in products:
    sl = shelf_life[p]
    for l in locations:
        for r in range(1, sl + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

for p in products:
    sl = shelf_life[p]
    for t in range(periods):
        m.addConstr(I[p, hub, t, sl] == Q[p, t], name=f"fresh_hub_{p}_{t}")

for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in range(periods):
            m.addConstr(I[p, l, t, sl] == gp.quicksum(T[p, l, t, r] for r in range(1, sl + 1)) * 0 + 
                        T[p, l, t, sl] if sl in range(1, sl + 1) else 0, name=f"fresh_spoke_{p}_{l}_{t}")

for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in range(periods):
            inbound = gp.quicksum(T[p, l, t, r] for r in range(1, sl + 1))
            m.addConstr(I[p, l, t, sl] == inbound, name=f"spoke_fresh_{p}_{l}_{t}")

for p in products:
    sl = shelf_life[p]
    for t in range(periods):
        for r in range(1, sl):
            outbound = gp.quicksum(T[p, l, t, r + 1] for l in spokes)
            m.addConstr(I[p, hub, t + 1, r] == I[p, hub, t, r + 1] - sales[p, hub, t, r + 1] - outbound,
                        name=f"aging_hub_{p}_{t}_{r}")

for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in range(periods):
            for r in range(1, sl):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1] + T[p, l, t, r + 1],
                            name=f"aging_spoke_{p}_{l}_{t}_{r}")

for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in range(periods):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in range(periods):
            for r in range(1, sl + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in range(periods):
            for r in range(1, sl + 1):
                m.addConstr(T[p, l, t, r] <= I[p, hub, t, r], name=f"trans_avail_{p}_{l}_{t}_{r}")

for p in products:
    for l in locations:
        for t in range(periods):
            local_demand = demand_curve[p][t] * demand_share[l]
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            sub_in = gp.quicksum(sub[p_from, p, l, t] for (p_from, p_to) in sub_edges if p_to == p)
            sub_out = gp.quicksum(sub[p, p_to, l, t] for (p_from, p_to) in sub_edges if p_from == p)
            m.addConstr(total_sales + sub_in + L[p, l, t] == local_demand + sub_out,
                        name=f"demand_{p}_{l}_{t}")

for (p_from, p_to) in sub_edges:
    for l in locations:
        for t in range(periods):
            avail = gp.quicksum(sales[p_from, l, t, r] for r in range(1, shelf_life[p_from] + 1))
            m.addConstr(sub[p_from, p_to, l, t] <= avail, name=f"sub_limit_{p_from}_{p_to}_{l}_{t}")

for l in locations:
    for t in range(periods):
        total_storage = gp.quicksum(
            cold_usage[p] * gp.quicksum(I[p, l, t, r] for r in range(1, shelf_life[p] + 1))
            for p in products
        )
        m.addConstr(total_storage <= cold_capacity[l], name=f"storage_{l}_{t}")

purchasing_cost = gp.quicksum(costs["purchasing"][p] * Q[p, t] for p in products for t in range(periods))

holding_cost = gp.quicksum(
    costs["inventory"][p] * (I[p, l, t, r] - sales[p, l, t, r])
    for p in products for l in locations for t in range(periods)
    for r in range(2, shelf_life[p] + 1)
)

waste_cost = gp.quicksum(costs["waste"][p] * W[p, l, t] for p in products for l in locations for t in range(periods))

lost_sales_cost = gp.quicksum(costs["lost_sales"][p] * L[p, l, t] for p in products for l in locations for t in range(periods))

trans_cost = gp.quicksum(
    costs["transshipment"] * T[p, l, t, r]
    for p in products for l in spokes for t in range(periods)
    for r in range(1, shelf_life[p] + 1)
)

m.setObjective(purchasing_cost + holding_cost + waste_cost + lost_sales_cost + trans_cost, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
