for p in products:
    for t in periods:
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# Fresh inflow at hub: I[p,hub,t,SL] = Q[p,t]
for p in products:
    sl = shelf_life[p]
    for t in periods:
        m.addConstr(I[p, hub, t, sl] == Q[p, t], name=f"fresh_hub_{p}_{t}")

# Fresh inflow at spokes: I[p,l,t,SL] = Trans[p,l,t,SL]
for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in periods:
            m.addConstr(I[p, l, t, sl] == Trans[p, l, t, sl], name=f"fresh_spoke_{p}_{l}_{t}")

# Transshipment availability: can only ship what hub has
for p in products:
    sl = shelf_life[p]
    for t in periods:
        for r in range(1, sl + 1):
            m.addConstr(
                gp.quicksum(Trans[p, l, t, r] for l in spokes) <= I[p, hub, t, r],
                name=f"trans_avail_{p}_{t}_{r}"
            )

# Aging at hub: I[p,hub,t+1,r] = I[p,hub,t,r+1] - sum_l Trans[p,l,t,r+1]
for p in products:
    sl = shelf_life[p]
    for t in periods:
        for r in range(1, sl):  # r from 1 to SL-1
            m.addConstr(
                I[p, hub, t + 1, r] == I[p, hub, t, r + 1] - gp.quicksum(Trans[p, l, t, r + 1] for l in spokes),
                name=f"aging_hub_{p}_{t}_{r}"
            )

# Aging at spokes: I[p,l,t+1,r] = I[p,l,t,r+1] + Trans[p,l,t,r+1] - sales[p,l,t,r+1]
for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in periods:
            for r in range(1, sl):  # r from 1 to SL-1
                m.addConstr(
                    I[p, l, t + 1, r] == I[p, l, t, r + 1] + Trans[p, l, t, r + 1] - sales[p, l, t, r + 1],
                    name=f"aging_spoke_{p}_{l}_{t}_{r}"
                )

# Waste at hub: W[p,hub,t] = I[p,hub,t,1] - sum_l Trans[p,l,t,1]
for p in products:
    for t in periods:
        m.addConstr(
            W[p, hub, t] == I[p, hub, t, 1] - gp.quicksum(Trans[p, l, t, 1] for l in spokes),
            name=f"waste_hub_{p}_{t}"
        )

# Waste at spokes: W[p,l,t] = I[p,l,t,1] + Trans[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in spokes:
        for t in periods:
            m.addConstr(
                W[p, l, t] == I[p, l, t, 1] + Trans[p, l, t, 1] - sales[p, l, t, 1],
                name=f"waste_spoke_{p}_{l}_{t}"
            )

# Sales availability: sales[p,l,t,r] <= I[p,l,t,r] + Trans[p,l,t,r]
for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in periods:
            for r in range(1, sl + 1):
                m.addConstr(
                    sales[p, l, t, r] <= I[p, l, t, r] + Trans[p, l, t, r],
                    name=f"sales_avail_{p}_{l}_{t}_{r}"
                )

# Demand satisfaction with substitution at spokes
# For products that can be substituted TO (e.g., SKU_Premium can receive from SKU_Basic)
sub_to = {p_to: p_from for (p_from, p_to) in sub_edges}
sub_from = {p_from: p_to for (p_from, p_to) in sub_edges}

for p in products:
    sl = shelf_life[p]
    for l in spokes:
        for t in periods:
            local_demand = demand_curve[p][t] * demand_share[l]
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, sl + 1))

            # Add substitution received (if this product can be substituted by another)
            sub_received = 0
            if p in sub_to:
                p_from = sub_to[p]
                sub_received = sub[p_from, p, l, t]

            # Subtract substitution given (if this product substitutes for another)
            sub_given = 0
            if p in sub_from:
                p_to = sub_from[p]
                sub_given = sub[p, p_to, l, t]

            m.addConstr(
                total_sales + sub_received - sub_given + L[p, l, t] == local_demand,
                name=f"demand_{p}_{l}_{t}"
            )

# Substitution limited by available sales of the substituting product
for (p_from, p_to) in sub_edges:
    sl_from = shelf_life[p_from]
    for l in spokes:
        for t in periods:
            # Substitution cannot exceed what's available after own demand
            m.addConstr(
                sub[p_from, p_to, l, t] <= gp.quicksum(sales[p_from, l, t, r] for r in range(1, sl_from + 1)),
                name=f"sub_limit_{p_from}_{p_to}_{l}_{t}"
            )

# Storage capacity at each location
for l in locations:
    for t in periods:
        total_inv = gp.quicksum(
            cold_usage[p] * (I[p, l, t, r] + (Trans[p, l, t, r] if l in spokes else 0) - 
                            (sales[p, l, t, r] if l in spokes else gp.quicksum(Trans[p, sp, t, r] for sp in spokes)))
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        # Simpler: just use start-of-period inventory
        total_inv_start = gp.quicksum(
            cold_usage[p] * I[p, l, t, r]
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        m.addConstr(total_inv_start <= cold_capacity[l], name=f"capacity_{l}_{t}")

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in periods:
        obj += costs["purchasing"][p] * Q[p, t]

# Inventory holding cost: charged on end-of-period inventory for r >= 2
for p in products:
    sl = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(2, sl + 1):  # r >= 2 only
                if l == hub:
                    # End of period at hub = I[p,hub,t,r] - Trans_out
                    end_inv = I[p, l, t, r] - gp.quicksum(Trans[p, sp, t, r] for sp in spokes)
                else:
                    # End of period at spoke = I[p,l,t,r] + Trans_in - sales
                    end_inv = I[p, l, t, r] + Trans[p, l, t, r] - sales[p, l, t, r]
                obj += costs["inventory"][p] * end_inv

# Waste cost
for p in products:
    for l in locations:
        for t in periods:
            obj += costs["waste"][p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in spokes:
        for t in periods:
            obj += costs["lost_sales"][p] * L[p, l, t]

# Transshipment cost
for p in products:
    for l in spokes:
        for t in periods:
            for r in range(1, shelf_life[p] + 1):
                obj += costs["transshipment"] * Trans[p, l, t, r]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

