  "demand_share": {"Plant": 0.0, "DC1": 0.0, "DC2": 0.0, "Store1": 0.3, "Store2": 0.4, "Store3": 0.3},
  "costs": {"lost_sales": {"SKU_Basic": 50.0, "SKU_Premium": 80.0, "SKU_ShortLife": 40.0}, "inventory": {"SKU_Basic": 1.0, "SKU_Premium": 1.5, "SKU_ShortLife": 1.0}, "waste": {"SKU_Basic": 2.0, "SKU_Premium": 3.0, "SKU_ShortLife": 2.0}, "fixed_order": 0.0, "transshipment": 0.5, "purchasing": {"SKU_Basic": 10.0, "SKU_Premium": 20.0, "SKU_ShortLife": 15.0}},
  "constraints": {"moq": 0, "pack_size": 1, "budget_per_period": null, "waste_limit_pct": null},
  "network": {"sub_edges": [["SKU_Basic", "SKU_Premium"]], "trans_edges": [["Plant", "DC1"], ["Plant", "DC2"], ["DC1", "Store1"], ["DC1", "Store2"], ["DC2", "Store2"], ["DC2", "Store3"]]}
}
"""

data = json.loads(json_data)

products = data["products"]
locations = data["locations"]
T = data["periods"]
shelf_life = data["shelf_life"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
costs = data["costs"]
trans_edges = [tuple(e) for e in data["network"]["trans_edges"]]

stores = ["Store1", "Store2", "Store3"]
dcs = ["DC1", "DC2"]

inbound_edges = {l: [] for l in locations}
outbound_edges = {l: [] for l in locations}
for (src, dst) in trans_edges:
    outbound_edges[src].append((src, dst))
    inbound_edges[dst].append((src, dst))

m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

Q = {}
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

Trans = {}
for p in products:
    SL = shelf_life[p]
    for (src, dst) in trans_edges:
        for t in range(T):
            for r in range(1, SL + 1):
                Trans[p, src, dst, t, r] = m.addVar(lb=0, name=f"Trans_{p}_{src}_{dst}_{t}_{r}")

sales = {}
for p in products:
    SL = shelf_life[p]
    for l in stores:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}
for p in products:
    for l in stores:
        for t in range(T):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

for p in products:
    SL = shelf_life[p]
    for t in range(T):
        m.addConstr(I[p, "Plant", t, SL] == Q[p, t], name=f"fresh_inflow_{p}_{t}")

for p in products:
    SL = shelf_life[p]
    for t in range(T):
        for r in range(1, SL):
            outbound = gp.quicksum(Trans[p, "Plant", dst, t, r + 1] for (src, dst) in outbound_edges["Plant"])
            m.addConstr(I[p, "Plant", t + 1, r] == I[p, "Plant", t, r + 1] - outbound, 
                       name=f"aging_plant_{p}_{t}_{r}")

for p in products:
    SL = shelf_life[p]
    for t in range(T):
        outbound_oldest = gp.quicksum(Trans[p, "Plant", dst, t, 1] for (src, dst) in outbound_edges["Plant"])
        m.addConstr(W[p, "Plant", t] == I[p, "Plant", t, 1] - outbound_oldest, 
                   name=f"waste_plant_{p}_{t}")

for dc in dcs:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            m.addConstr(I[p, dc, t, SL] == 0, name=f"no_fresh_{p}_{dc}_{t}")

for dc in dcs:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            for r in range(1, SL):
                inbound = gp.quicksum(Trans[p, src, dc, t, r + 1] for (src, dst) in inbound_edges[dc])
                outbound = gp.quicksum(Trans[p, dc, dst, t, r + 1] for (src, dst) in outbound_edges[dc])
                m.addConstr(I[p, dc, t + 1, r] == I[p, dc, t, r + 1] + inbound - outbound,
                           name=f"aging_dc_{p}_{dc}_{t}_{r}")

for dc in dcs:
    for p in products:
        for t in range(T):
            inbound_oldest = gp.quicksum(Trans[p, src, dc, t, 1] for (src, dst) in inbound_edges[dc])
            outbound_oldest = gp.quicksum(Trans[p, dc, dst, t, 1] for (src, dst) in outbound_edges[dc])
            m.addConstr(W[p, dc, t] == I[p, dc, t, 1] + inbound_oldest - outbound_oldest,
                       name=f"waste_dc_{p}_{dc}_{t}")

for store in stores:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            m.addConstr(I[p, store, t, SL] == 0, name=f"no_fresh_{p}_{store}_{t}")

for store in stores:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            for r in range(1, SL):
                inbound = gp.quicksum(Trans[p, src, store, t, r + 1] for (src, dst) in inbound_edges[store])
                m.addConstr(I[p, store, t + 1, r] == I[p, store, t, r + 1] + inbound - sales[p, store, t, r + 1],
                           name=f"aging_store_{p}_{store}_{t}_{r}")

for store in stores:
    for p in products:
        for t in range(T):
            inbound_oldest = gp.quicksum(Trans[p, src, store, t, 1] for (src, dst) in inbound_edges[store])
            m.addConstr(W[p, store, t] == I[p, store, t, 1] + inbound_oldest - sales[p, store, t, 1],
                       name=f"waste_store_{p}_{store}_{t}")

for store in stores:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            for r in range(1, SL + 1):
                inbound = gp.quicksum(Trans[p, src, store, t, r] for (src, dst) in inbound_edges[store])
                m.addConstr(sales[p, store, t, r] <= I[p, store, t, r] + inbound,
                           name=f"sales_avail_{p}_{store}_{t}_{r}")

for store in stores:
    for p in products:
        SL = shelf_life[p]
        for t in range(T):
            total_sales = gp.quicksum(sales[p, store, t, r] for r in range(1, SL + 1))
            local_demand = demand_curve[p][t] * demand_share[store]
            m.addConstr(total_sales + L[p, store, t] == local_demand,
                       name=f"demand_sat_{p}_{store}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                outbound = gp.quicksum(Trans[p, l, dst, t, r] for (src, dst) in outbound_edges[l]) if outbound_edges[l] else 0
                m.addConstr(outbound <= I[p, l, t, r], name=f"trans_avail_{p}_{l}_{t}_{r}")

for l in locations:
    for t in range(T):
        total_inv = gp.quicksum(
            cold_usage[p] * I[p, l, t, r]
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        m.addConstr(total_inv <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

purchasing_cost = gp.quicksum(costs["purchasing"][p] * Q[p, t] for p in products for t in range(T))

holding_cost = gp.quicksum(
    costs["inventory"][p] * (I[p, l, t, r] - 
        (sales.get((p, l, t, r), 0) if l in stores else 0) -
        gp.quicksum(Trans[p, l, dst, t, r] for (src, dst) in outbound_edges[l]))
    for p in products
    for l in locations
    for t in range(T)
    for r in range(2, shelf_life[p] + 1)
)

transshipment_cost = gp.quicksum(
    costs["transshipment"] * Trans[p, src, dst, t, r]
    for p in products
    for (src, dst) in trans_edges
    for t in range(T)
    for r in range(1, shelf_life[p] + 1)
)

waste_cost = gp.quicksum(costs["waste"][p] * W[p, l, t] for p in products for l in locations for t in range(T))

lost_sales_cost = gp.quicksum(costs["lost_sales"][p] * L[p, l, t] for p in products for l in stores for t in range(T))

m.setObjective(purchasing_cost + holding_cost + transshipment_cost + waste_cost + lost_sales_cost, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost consisting of:
- Purchasing costs (production)
- Inventory holding costs
- Waste costs (expired products)
- Lost sales costs (unmet demand)
- Transshipment costs (moving inventory along the ring)

**Decisions to make:**
- Q[p,t]: Production quantity for product p in period t
- I[p,l,t,r]: Inventory of product p at location l at start of period t with r periods remaining
- sales[p,l,t,r]: Sales of product p at location l in period t from inventory with r periods remaining
- W[p,l,t]: Waste of product p at location l in period t
- L[p,l,t]: Lost sales of product p at location l in period t
- T[p,l1,l2,t,r]: Transshipment of product p from l1 to l2 in period t with r periods remaining

**Constraints:**
1. Production capacity limits
2. Storage capacity at each location
3. Inventory balance with aging (FIFO)
4. Sales limited by inventory availability
5. Demand satisfaction (sales + lost sales = demand)
6. Transshipment only along ring edges (DC1→DC2→DC3→DC4→DC5→DC1)
7. Non-negativity

**Parameters:** Products, locations, periods, shelf life, demand curves, demand shares, costs, capacities, ring network structure.

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P: Products {SKU_Basic, SKU_Premium, SKU_ShortLife}
- L: Locations {DC1, DC2, DC3, DC4, DC5}
- T: Periods {0, 1, ..., 19}
- R[p]: Remaining life values {1, 2, ..., shelf_life[p]}
- E: Ring edges {(DC1,DC2), (DC2,DC3), (DC3,DC4), (DC4,DC5), (DC5,DC1)}

**Parameters:**
- SL[p]: Shelf life of product p
- demand[p,t]: Total demand for product p in period t
- share[l]: Demand share at location l
- prod_cap[p,t]: Production capacity
- cold_cap[l]: Cold storage capacity
- cold_use[p]: Cold storage usage per unit
- c_purch[p], c_inv[p], c_waste[p], c_lost[p], c_trans: Costs

**Decision Variables (all CONTINUOUS since fractional units are acceptable):**
- Q[p,t] ≥ 0: Production of product p in period t
- I[p,l,t,r] ≥ 0: Inventory at start of period t with r remaining
- sales[p,l,t,r] ≥ 0: Sales from inventory with r remaining
- W[p,l,t] ≥ 0: Waste
- L[p,l,t] ≥ 0: Lost sales
- T_out[p,l,t,r] ≥ 0: Transshipment out from location l
- T_in[p,l,t,r] ≥ 0: Transshipment into location l

**Constraints:**

1. **Fresh inflow (r = SL[p]):**
   I[p,l,t,SL[p]] = Q[p,t] * share[l] + T_in[p,l,t,SL[p]] - T_out[p,l,t,SL[p]]

2. **Aging (for r = 1 to SL[p]-1):**
   I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] + T_in[p,l,t,r+1] - T_out[p,l,t,r+1]

3. **Waste:**
   W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1] + T_in[p,l,t,1] - T_out[p,l,t,1]

4. **Sales availability:**
   sales[p,l,t,r] ≤ I[p,l,t,r] + T_in[p,l,t,r]

5. **Demand satisfaction:**
   Σ_r sales[p,l,t,r] + L[p,l,t] = demand[p,t] * share[l]

6. **Production capacity:**
   Q[p,t] ≤ prod_cap[p,t]

7. **Storage capacity:**
   Σ_p Σ_r cold_use[p] * (I[p,l,t,r] + T_in[p,l,t,r] - sales[p,l,t,r]) ≤ cold_cap[l]

8. **Ring transshipment balance:**
   For each edge (l1, l2): T_out[p,l1,t,r] flows to T_in[p,l2,t,r]

**Objective:**
Minimize: Σ c_purch[p]*Q[p,t] + Σ c_inv[p]*(I[p,l,t,r]-sales[p,l,t,r]) for r≥2 + Σ c_waste[p]*W[p,l,t] + Σ c_lost[p]*L[p,l,t] + Σ c_trans*T_out[p,l,t,r]

```python
import gurobipy as gp
from gurobipy import GRB
import json

json_data = """
{
  "name": "retail_f7_ring_routing_v1",
  "description": "Standard seasonal retail scenario.",
  "periods": 20,
  "products": ["SKU_Basic", "SKU_Premium", "SKU_ShortLife"],
  "locations": ["DC1", "DC2", "DC3", "DC4", "DC5"],
  "shelf_life": {"SKU_Basic": 10, "SKU_Premium": 8, "SKU_ShortLife": 4},
  "lead_time": {"SKU_Basic": 0, "SKU_Premium": 0, "SKU_ShortLife": 0},
  "cold_capacity": {"DC1": 2991.8326868227214, "DC2": 2532.9007952808656, "DC3": 2608.4258534753153, "DC4": 2118.6262010983583, "DC5": 2207.6219002477706},
  "cold_usage": {"SKU_Basic": 1.0, "SKU_Premium": 3.0, "SKU_ShortLife": 1.2},
  "production_cap": {"SKU_Basic": [800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800,800], "SKU_Premium": [400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400,400], "SKU_ShortLife": [500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500,500]},
  "labor_cap": {"DC1": [99999.0]*20, "DC2": [99999.0]*20, "DC3": [99999.0]*20, "DC4": [99999.0]*20, "DC5": [99999.0]*20},
  "labor_usage": {"SKU_Basic": 0.0, "SKU_Premium": 0.0, "SKU_ShortLife": 0.0},
  "return_rate": {"SKU_Basic": 0.0, "SKU_Premium": 0.0, "SKU_ShortLife": 0.0},
  "demand_curve": {"SKU_Basic": [342,293,376,397,429,588,811,952,1238,1392,1210,1308,1038,1007,614,540,496,335,330,270], "SKU_Premium": [135,140,159,203,203,238,356,489,624,593,583,576,608,468,357,252,220,192,178,148], "SKU_ShortLife": [125,132,136,149,185,248,318,366,375,542,502,484,374,326,272,224,174,161,121,105]},
  "demand_share": {"DC1": 0.25, "DC2": 0.2, "DC3": 0.2, "DC4": 0.2, "DC5": 0.15},
  "costs": {"lost_sales": {"SKU_Basic": 50.0, "SKU_Premium": 80.0, "SKU_ShortLife": 40.0}, "inventory": {"SKU_Basic": 1.0, "SKU_Premium": 1.5, "SKU_ShortLife": 1.0}, "waste": {"SKU_Basic": 2.0, "SKU_Premium": 3.0, "SKU_ShortLife": 2.0}, "fixed_order": 0.0, "transshipment": 0.5, "purchasing": {"SKU_Basic": 10.0, "SKU_Premium": 20.0, "SKU_ShortLife": 15.0}},
  "constraints": {"moq": 0, "pack_size": 1, "budget_per_period": null, "waste_limit_pct": null},
  "network": {"sub_edges": [["SKU_Basic", "SKU_Premium"]], "trans_edges": [["DC1", "DC2"], ["DC2", "DC3"], ["DC3", "DC4"], ["DC4", "DC5"], ["DC5", "DC1"]]}
}
"""

data = json.loads(json_data)

products = data["products"]
locations = data["locations"]
num_periods = data["periods"]
periods = range(num_periods)
shelf_life = data["shelf_life"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
production_cap = data["production_cap"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
trans_edges = data["network"]["trans_edges"]
costs = data["costs"]

c_purch = costs["purchasing"]
c_inv = costs["inventory"]
c_waste = costs["waste"]
c_lost = costs["lost_sales"]
c_trans = costs["transshipment"]

# Build ring edge mapping
ring_next = {e[0]: e[1] for e in trans_edges}

m = gp.Model("ring_routing")
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production Q[p,t]
for p in products:
    for t in periods:
        Q[p,t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

# Inventory I[p,l,t,r] - inventory at START of period t with r periods remaining
I = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, SL+1):
                I[p,l,t,r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

# Sales sales[p,l,t,r]
sales = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, SL+1):
                sales[p,l,t,r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

# Waste W[p,l,t]
W = {}
for p in products:
    for l in locations:
        for t in periods:
            W[p,l,t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

# Lost sales L[p,l,t]
L = {}
for p in products:
    for l in locations:
        for t in periods:
            L[p,l,t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

# Transshipment T[p,l_from,l_to,t,r] - only along ring edges
T = {}
for p in products:
    SL = shelf_life[p]
    for (l_from, l_to) in trans_edges:
        for t in periods:
            for r in range(1, SL+1):
                T[p,l_from,l_to,t,r] = m.addVar(lb=0, name=f"T_{p}_{l_from}_{l_to}_{t}_{r}")

m.update()

# Constraints

# 1. Production capacity
for p in products:
    for t in periods:
        m.addConstr(Q[p,t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# Helper functions for transshipment in/out
def trans_out(p, l, t, r):
    l_to = ring_next[l]
    return T[p,l,l_to,t,r]

def trans_in(p, l, t, r):
    # Find which location sends to l
    for (l_from, l_to) in trans_edges:
        if l_to == l:
            return T[p,l_from,l,t,r]
    return 0

# 2. Fresh inflow constraint (r = SL[p]) for t=0
for p in products:
    SL = shelf_life[p]
    for l in locations:
        # Period 0: fresh inventory comes from production
        m.addConstr(
            I[p,l,0,SL] == Q[p,0] * demand_share[l] + trans_in(p,l,0,SL) - trans_out(p,l,0,SL),
            name=f"fresh_inflow_{p}_{l}_0"
        )

# 3. Aging constraints and fresh inflow for t >= 1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(num_periods - 1):
            # Fresh inflow for next period
            m.addConstr(
                I[p,l,t+1,SL] == Q[p,t+1] * demand_share[l] + trans_in(p,l,t+1,SL) - trans_out(p,l,t+1,SL),
                name=f"fresh_inflow_{p}_{l}_{t+1}"
            )
            # Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] + trans_in - trans_out
            for r in range(1, SL):
                m.addConstr(
                    I[p,l,t+1,r] == I[p,l,t,r+1] - sales[p,l,t,r+1] + trans_in(p,l,t,r+1) - trans_out(p,l,t,r+1),
                    name=f"aging_{p}_{l}_{t}_{r}"
                )

# 4. Waste constraint: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1] + trans_in - trans_out
for p in products:
    for l in locations:
        for t in periods:
            m.addConstr(
                W[p,l,t] == I[p,l,t,1] - sales[p,l,t,1] + trans_in(p,l,t,1) - trans_out(p,l,t,1),
                name=f"waste_{p}_{l}_{t}"
            )

# 5. Sales availability: sales[p,l,t,r] <= I[p,l,t,r] + trans_in[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(1, SL+1):
                m.addConstr(
                    sales[p,l,t,r] <= I[p,l,t,r] + trans_in(p,l,t,r),
                    name=f"sales_avail_{p}_{l}_{t}_{r}"
                )

# 6. Demand satisfaction: sum of sales + lost sales = local demand
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            local_demand = demand_curve[p][t] * demand_share[l]
            m.addConstr(
                gp.quicksum(sales[p,l,t,r] for r in range(1, SL+1)) + L[p,l,t] == local_demand,
                name=f"demand_{p}_{l}_{t}"
            )

# 7. Storage capacity constraint
for l in locations:
    for t in periods:
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * (I[p,l,t,r] + trans_in(p,l,t,r) - sales[p,l,t,r])
                for p in products
                for r in range(2, shelf_life[p]+1)
            ) + gp.quicksum(
                cold_usage[p] * W[p,l,t]  # r=1 items that become waste still occupy space during period
                for p in products
            ) <= cold_capacity[l],
            name=f"storage_{l}_{t}"
        )

# Objective function
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in periods:
        obj += c_purch[p] * Q[p,t]

# Inventory holding cost (on end-of-period inventory, r >= 2)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in periods:
            for r in range(2, SL+1):
                obj += c_inv[p] * (I[p,l,t,r] + trans_in(p,l,t,r) - sales[p,l,t,r])

# Waste cost
for p in products:
    for l in locations:
        for t in periods:
            obj += c_waste[p] * W[p,l,t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in periods:
            obj += c_lost[p] * L[p,l,t]

# Transshipment cost
for p in products:
    SL = shelf_life[p]
    for (l_from, l_to) in trans_edges:
        for t in periods:
            for r in range(1, SL+1):
                obj += c_trans * T[p,l_from,l_to,t,r]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost including:
- Purchasing costs (production)
- Inventory holding costs
- Waste costs (expired products)
- Lost sales costs (unmet demand)
- Transshipment costs (moving inventory between locations)

**Decisions to make:**
1. How much to produce of each product in each period (Q[p,t])
2. How much inventory to hold at each location by remaining life (I[p,l,t,r])
3. How much to sell at each location by remaining life (sales[p,l,t,r])
4. How much to transship between locations (T[p,l1,l2,t,r])
5. How much waste occurs (W[p,l,t])
6. How much demand is lost (L[p,l,t])

**Constraints:**
- Production capacity limits
- Cold storage capacity at each location
- FIFO sales (sell oldest first)
- Inventory balance with aging
- Transshipment flow limits
- Demand satisfaction or lost sales
- Non-negativity

**Parameters:**
- 20 periods, 3 products, 5 locations
- Shelf life varies by product (10, 8, 4 periods)
- Demand curves and demand shares by location
- Various costs (purchasing, holding, waste, lost sales, transshipment)

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets and Indices:**
- P: products
- L: locations
- T: periods {0, 1, ..., 19}
- R[p]: remaining life {1, 2, ..., shelf_life[p]}
- E: transshipment edges (l1, l2)

**Parameters:**
- SL[p]: shelf life of product p
- demand[p,t]: total demand for product p in period t
- share[l]: demand share for location l
- cap[p,t]: production capacity
- cold_cap[l]: cold storage capacity
- cold_use[p]: cold storage usage per unit
- c_purch[p], c_inv[p], c_waste[p], c_lost[p], c_trans: costs

**Decision Variables:**
- Q[p,t] ≥ 0: production quantity (CONTINUOUS - fractional production is reasonable)
- I[p,l,t,r] ≥ 0: inventory at start of period t with r periods remaining (CONTINUOUS)
- sales[p,l,t,r] ≥ 0: sales from inventory with r remaining (CONTINUOUS)
- T[p,l1,l2,t,r] ≥ 0: transshipment from l1 to l2 (CONTINUOUS)
- W[p,l,t] ≥ 0: waste (CONTINUOUS)
- L[p,l,t] ≥ 0: lost sales (CONTINUOUS)

**Constraints:**

1. **Fresh inflow (t=0 to T-1):**
   I[p,l,t,SL[p]] = Q[p,t] * share[l]

2. **Aging (for r=1 to SL-1, t=0 to T-2):**
   I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] + net_transship_in[p,l,t,r+1]

3. **Waste:**
   W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1] + net_transship_in[p,l,t,1]

4. **Sales availability:**
   sales[p,l,t,r] ≤ I[p,l,t,r] + transship_in[p,l,t,r] - transship_out[p,l,t,r]

5. **Demand satisfaction (FIFO):**
   sum_r(sales[p,l,t,r]) + L[p,l,t] = demand[p,t] * share[l]

6. **Production capacity:**
   Q[p,t] ≤ cap[p,t]

7. **Cold storage capacity:**
   sum_p(cold_use[p] * sum_r(I[p,l,t,r] - sales[p,l,t,r] + net_trans[p,l,t,r])) ≤ cold_cap[l]

8. **Transshipment limits:**
   sum_{l2}(T[p,l,l2,t,r]) ≤ I[p,l,t,r]

9. **Initial inventory (t=0, r < SL):**
   I[p,l,0,r] = 0 for r < SL[p]

**Objective:**
Minimize: sum of purchasing + holding + waste + lost sales + transshipment costs

```python
import gurobipy as gp
from gurobipy import GRB
import json

# Data is pre-defined
products = data["products"]
locations = data["locations"]
T = data["num_periods"]
shelf_life = data["shelf_life"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
production_cap = data["production_cap"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
c_purch = data["cost_purchasing"]
c_inv = data["cost_inventory"]
c_waste = data["cost_waste"]
c_lost = data["cost_lost_sales"]
c_trans = data["cost_transshipment"]

# Build trans_edges list
trans_edges = []
for l1 in locations:
    for l2 in locations:
        if l1 != l2:
            trans_edges.append((l1, l2))

# Create model
m = gp.Model()
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory by remaining life
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales by remaining life
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

Trans = {}  # Transshipment by remaining life
for p in products:
    SL = shelf_life[p]
    for (l1, l2) in trans_edges:
        for t in range(T):
            for r in range(1, SL + 1):
                Trans[p, l1, l2, t, r] = m.addVar(lb=0, name=f"Trans_{p}_{l1}_{l2}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(T):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

m.update()

# Constraints

# 1. Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# 2. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

# 3. Initial inventory for non-fresh (t=0, r < SL)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_{p}_{l}_{r}")

# Helper: net transshipment in for a location
def trans_in(p, l, t, r):
    return gp.quicksum(Trans[p, l2, l, t, r] for l2 in locations if l2 != l)

def trans_out(p, l, t, r):
    return gp.quicksum(Trans[p, l, l2, t, r] for l2 in locations if l2 != l)

# 4. Aging constraint: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] + trans_in - trans_out
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T - 1):
            for r in range(1, SL):
                m.addConstr(
                    I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1] 
                    + trans_in(p, l, t, r + 1) - trans_out(p, l, t, r + 1),
                    name=f"aging_{p}_{l}_{t}_{r}"
                )

# 5. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1] + trans_in - trans_out
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(
                W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1] 
                + trans_in(p, l, t, 1) - trans_out(p, l, t, 1),
                name=f"waste_{p}_{l}_{t}"
            )

# 6. Sales availability: sales[p,l,t,r] <= I[p,l,t,r] + trans_in - trans_out
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(
                    sales[p, l, t, r] <= I[p, l, t, r] + trans_in(p, l, t, r) - trans_out(p, l, t, r),
                    name=f"sales_avail_{p}_{l}_{t}_{r}"
                )

# 7. Transshipment out limit: can't ship more than you have
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(
                    trans_out(p, l, t, r) <= I[p, l, t, r],
                    name=f"trans_out_limit_{p}_{l}_{t}_{r}"
                )

# 8. Demand satisfaction: sum_r(sales) + L = demand * share
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            local_demand = demand_curve[p][t] * demand_share[l]
            m.addConstr(
                gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + L[p, l, t] == local_demand,
                name=f"demand_{p}_{l}_{t}"
            )

# 9. Cold storage capacity (end of period inventory)
for l in locations:
    for t in range(T):
        end_inv = gp.quicksum(
            cold_usage[p] * (I[p, l, t, r] - sales[p, l, t, r] + trans_in(p, l, t, r) - trans_out(p, l, t, r))
            for p in products
            for r in range(2, shelf_life[p] + 1)  # exclude r=1 (expiring)
        )
        m.addConstr(end_inv <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += c_purch[p] * Q[p, t]

# Inventory holding cost (on end-of-period inventory, r >= 2)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += c_inv[p] * (I[p, l, t, r] - sales[p, l, t, r] + trans_in(p, l, t, r) - trans_out(p, l, t, r))

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += c_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += c_lost[p] * L[p, l, t]

# Transshipment cost
for p in products:
    SL = shelf_life[p]
    for (l1, l2) in trans_edges:
        for t in range(T):
            for r in range(1, SL + 1):
                obj += c_trans * Trans[p, l1, l2, t, r]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
