        for t in T:
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1],
                       name=f"waste_{p}_{l}_{t}")

# 4. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r],
                           name=f"sales_avail_{p}_{l}_{t}_{r}")

# 5. Demand satisfaction: sum_r(sales[p,l,t,r]) + L[p,l,t] = demand[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            local_demand = demand_curve[p][t] * demand_share[l]
            m.addConstr(
                gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)) + L[p, l, t] == local_demand,
                name=f"demand_{p}_{l}_{t}"
            )

# 6. Production capacity: Q[p,t] <= production_cap[p,t]
for p in products:
    for t in T:
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# 7. Cold storage capacity: sum_p,r(cold_usage[p] * I[p,l,t,r]) <= cold_capacity[l]
for l in locations:
    for t in T:
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * I[p, l, t, r]
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l],
            name=f"cold_cap_{l}_{t}"
        )

# 8. Labor capacity: labor for receiving + picking <= labor_cap
# Units handled = receiving (Q[p,t]*demand_share[l]) + picking (sum of sales)
for l in locations:
    for t in T:
        m.addConstr(
            gp.quicksum(
                labor_usage[p] * (
                    Q[p, t] * demand_share[l] + 
                    gp.quicksum(sales[p, l, t, r] for r in range(1, shelf_life[p] + 1))
                )
                for p in products
            ) <= labor_cap[l][t],
            name=f"labor_cap_{l}_{t}"
        )

# Initial inventory constraints (period 0, non-fresh inventory is 0)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):  # r < SL (not fresh)
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# Objective function
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in T:
        obj += cost_purchasing[p] * Q[p, t]

# Inventory holding cost (on end-of-period inventory for r >= 2)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in T:
            for r in range(2, SL + 1):
                obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in T:
            obj += cost_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in T:
            obj += cost_lost_sales[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

# Optimize
m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost including:
- Purchasing costs (production)
- Inventory holding costs
- Waste costs (expired items)
- Lost sales costs

**Decisions to make:**
- Q[p,t]: Production quantity for each product in each period
- sales[p,l,t,r]: Sales from inventory with remaining life r
- I[p,l,t,r]: Inventory at start of period t with r periods remaining
- W[p,l,t]: Waste (expired items)
- L[p,l,t]: Lost sales

**Constraints:**
1. Fresh inflow from production distributed by demand_share
2. Returns re-enter as fresh inventory (age = shelf_life)
3. Aging dynamics: inventory ages each period
4. Sales limited by available inventory
5. Demand satisfaction: total sales + lost sales = demand
6. Cold storage capacity limits
7. Production capacity limits
8. Non-negativity

**Key feature - Returns:** A fraction of sales in period t returns in period t+1 as fresh inventory.

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P = {SKU_Basic, SKU_Premium, SKU_ShortLife} - products
- L = {DC1, DC2, DC3, DC4, DC5} - locations
- T = {0, 1, ..., 19} - periods
- R[p] = {1, 2, ..., shelf_life[p]} - remaining life values

**Parameters:**
- shelf_life[p]: shelf life of product p
- demand[p,t]: total demand for product p in period t
- demand_share[l]: fraction of demand/production at location l
- return_rate[p]: fraction of sales returned next period
- cold_capacity[l]: storage capacity at location l
- cold_usage[p]: storage units per item of product p
- production_cap[p,t]: max production of product p in period t
- Various costs: purchasing, inventory, waste, lost_sales

**Decision Variables:**
- Q[p,t] ≥ 0: Production quantity (CONTINUOUS - fractional units acceptable)
- I[p,l,t,r] ≥ 0: Inventory at start of period t with r remaining (CONTINUOUS)
- sales[p,l,t,r] ≥ 0: Sales from inventory with r remaining (CONTINUOUS)
- W[p,l,t] ≥ 0: Waste (CONTINUOUS)
- Lost[p,l,t] ≥ 0: Lost sales (CONTINUOUS)
- Returns[p,l,t] ≥ 0: Returns entering inventory (CONTINUOUS)

**Constraints:**

1. **Fresh inflow (Eq 1):** 
   I[p,l,t,SL[p]] = Q[p,t] * demand_share[l] + Returns[p,l,t]

2. **Returns calculation:**
   Returns[p,l,t] = return_rate[p] * sum_r(sales[p,l,t-1,r]) for t > 0
   Returns[p,l,0] = 0

3. **Aging (Eq 2):**
   I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r = 1..SL-1

4. **Waste (Eq 3):**
   W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]

5. **Sales availability (Eq 4):**
   sales[p,l,t,r] ≤ I[p,l,t,r]

6. **Demand satisfaction:**
   sum_r(sales[p,l,t,r]) + Lost[p,l,t] = demand[p,t] * demand_share[l]

7. **Cold storage capacity:**
   sum_p,r(cold_usage[p] * (I[p,l,t,r] - sales[p,l,t,r])) ≤ cold_capacity[l]

8. **Production capacity:**
   Q[p,t] ≤ production_cap[p,t]

**Objective:** Minimize
- sum_{p,t} purchasing[p] * Q[p,t]
- + sum_{p,l,t,r≥2} inventory[p] * (I[p,l,t,r] - sales[p,l,t,r])
- + sum_{p,l,t} waste[p] * W[p,l,t]
- + sum_{p,l,t} lost_sales[p] * Lost[p,l,t]

