production_cap = data["production_cap"]
cost_purchasing = data["costs"]["purchasing"]
cost_inventory = data["costs"]["inventory"]
cost_waste = data["costs"]["waste"]
cost_lost_sales = data["costs"]["lost_sales"]

m = gp.Model("reverse_logistics")
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

# Decision variables
Q = {}  # Production
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}  # Inventory I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}  # Sales by age
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}  # Waste
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

L = {}  # Lost sales
for p in products:
    for l in locations:
        for t in range(T):
            L[p, l, t] = m.addVar(lb=0, name=f"L_{p}_{l}_{t}")

# Auxiliary variable for total sales at location (for returns calculation)
total_sales = {}
for p in products:
    for l in locations:
        for t in range(T):
            total_sales[p, l, t] = m.addVar(lb=0, name=f"total_sales_{p}_{l}_{t}")

m.update()

# Constraints

# 1. Production capacity
for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

# 2. Total sales definition
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(
                total_sales[p, l, t] == gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1)),
                name=f"total_sales_def_{p}_{l}_{t}"
            )

# 3. Fresh inflow: I[p,l,t,SL] = Q[p,t] * demand_share[l] + returns
# Returns from period t-1 re-enter as fresh inventory in period t
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            if t == 0:
                # No returns in first period
                m.addConstr(
                    I[p, l, t, SL] == Q[p, t] * demand_share[l],
                    name=f"fresh_inflow_{p}_{l}_{t}"
                )
            else:
                # Returns from previous period
                m.addConstr(
                    I[p, l, t, SL] == Q[p, t] * demand_share[l] + return_rate[p] * total_sales[p, l, t-1],
                    name=f"fresh_inflow_{p}_{l}_{t}"
                )

# 4. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T - 1):
            for r in range(1, SL):
                m.addConstr(
                    I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1],
                    name=f"aging_{p}_{l}_{t}_{r}"
                )

# 5. Initial inventory for non-fresh ages (t=0, r < SL)
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_inv_{p}_{l}_{r}")

# 6. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]
for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(
                W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1],
                name=f"waste_{p}_{l}_{t}"
            )

# 7. Sales availability: sales[p,l,t,r] <= I[p,l,t,r]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(
                    sales[p, l, t, r] <= I[p, l, t, r],
                    name=f"sales_avail_{p}_{l}_{t}_{r}"
                )

# 8. Demand satisfaction: total_sales + lost_sales = demand
for p in products:
    for l in locations:
        for t in range(T):
            local_demand = demand_curve[p][t] * demand_share[l]
            m.addConstr(
                total_sales[p, l, t] + L[p, l, t] == local_demand,
                name=f"demand_{p}_{l}_{t}"
            )

# 9. Cold storage capacity
for l in locations:
    for t in range(T):
        m.addConstr(
            gp.quicksum(
                cold_usage[p] * I[p, l, t, r]
                for p in products
                for r in range(1, shelf_life[p] + 1)
            ) <= cold_capacity[l],
            name=f"cold_cap_{l}_{t}"
        )

# Objective: minimize total cost
obj = gp.LinExpr()

# Purchasing cost
for p in products:
    for t in range(T):
        obj += cost_purchasing[p] * Q[p, t]

# Inventory holding cost: charged on (I[p,l,t,r] - sales[p,l,t,r]) for r >= 2
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

# Waste cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_waste[p] * W[p, l, t]

# Lost sales cost
for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_lost_sales[p] * L[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
