# Eq 1: Fresh inflow - I[p,l,t,SL] = Q[p,t] * demand_share[l]
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l],
