  "constraints": {
    "moq": 0,
    "pack_size": 1,
    "budget_per_period": null,
    "waste_limit_pct": 0.02
  },
  "network": {
    "sub_edges": [
      ["SKU_Basic", "SKU_Premium"]
    ],
    "trans_edges": []
  }
}
"""

data = json.loads(json_data)

products = data["products"]
locations = data["locations"]
T = data["periods"]
shelf_life = data["shelf_life"]
demand_curve = data["demand_curve"]
demand_share = data["demand_share"]
cold_capacity = data["cold_capacity"]
cold_usage = data["cold_usage"]
production_cap = data["production_cap"]
cost_purchasing = data["costs"]["purchasing"]
cost_inventory = data["costs"]["inventory"]
cost_waste = data["costs"]["waste"]
cost_lost_sales = data["costs"]["lost_sales"]
waste_limit_pct = data["constraints"]["waste_limit_pct"]
sub_edges = data["network"]["sub_edges"]

m = gp.Model("retail_sustainability")
m.Params.OutputFlag = 0
m.Params.Threads = 1
m.Params.Seed = 0

Q = {}
for p in products:
    for t in range(T):
        Q[p, t] = m.addVar(lb=0, name=f"Q_{p}_{t}")

I = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T + 1):
            for r in range(1, SL + 1):
                I[p, l, t, r] = m.addVar(lb=0, name=f"I_{p}_{l}_{t}_{r}")

sales = {}
for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                sales[p, l, t, r] = m.addVar(lb=0, name=f"sales_{p}_{l}_{t}_{r}")

W = {}
for p in products:
    for l in locations:
        for t in range(T):
            W[p, l, t] = m.addVar(lb=0, name=f"W_{p}_{l}_{t}")

lost = {}
for p in products:
    for l in locations:
        for t in range(T):
            lost[p, l, t] = m.addVar(lb=0, name=f"lost_{p}_{l}_{t}")

sub = {}
for edge in sub_edges:
    p_from, p_to = edge[0], edge[1]
    for l in locations:
        for t in range(T):
            sub[p_from, p_to, l, t] = m.addVar(lb=0, name=f"sub_{p_from}_{p_to}_{l}_{t}")

for p in products:
    for t in range(T):
        m.addConstr(Q[p, t] <= production_cap[p][t], name=f"prod_cap_{p}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            m.addConstr(I[p, l, t, SL] == Q[p, t] * demand_share[l], name=f"fresh_{p}_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for r in range(1, SL + 1):
            m.addConstr(I[p, l, 0, r] == 0, name=f"init_{p}_{l}_{r}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL):
                m.addConstr(I[p, l, t + 1, r] == I[p, l, t, r + 1] - sales[p, l, t, r + 1],
                            name=f"aging_{p}_{l}_{t}_{r}")

for p in products:
    for l in locations:
        for t in range(T):
            m.addConstr(W[p, l, t] == I[p, l, t, 1] - sales[p, l, t, 1], name=f"waste_{p}_{l}_{t}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(1, SL + 1):
                m.addConstr(sales[p, l, t, r] <= I[p, l, t, r], name=f"sales_avail_{p}_{l}_{t}_{r}")

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            demand_plt = demand_curve[p][t] * demand_share[l]
            total_sales = gp.quicksum(sales[p, l, t, r] for r in range(1, SL + 1))
            sub_in = gp.quicksum(sub[p_from, p, l, t] for (p_from, p_to) in sub_edges if p_to == p)
            sub_out = gp.quicksum(sub[p, p_to, l, t] for (p_from, p_to) in sub_edges if p_from == p)
            m.addConstr(total_sales + lost[p, l, t] + sub_out - sub_in == demand_plt,
                        name=f"demand_{p}_{l}_{t}")

for edge in sub_edges:
    p_from, p_to = edge[0], edge[1]
    SL_from = shelf_life[p_from]
    for l in locations:
        for t in range(T):
            avail = gp.quicksum(I[p_from, l, t, r] - sales[p_from, l, t, r] for r in range(1, SL_from + 1))
            m.addConstr(sub[p_from, p_to, l, t] <= avail, name=f"sub_avail_{p_from}_{p_to}_{l}_{t}")

for l in locations:
    for t in range(T):
        total_inv = gp.quicksum(
            cold_usage[p] * I[p, l, t, r]
            for p in products
            for r in range(1, shelf_life[p] + 1)
        )
        m.addConstr(total_inv <= cold_capacity[l], name=f"cold_cap_{l}_{t}")

total_demand = sum(demand_curve[p][t] for p in products for t in range(T))
total_waste = gp.quicksum(W[p, l, t] for p in products for l in locations for t in range(T))
m.addConstr(total_waste <= waste_limit_pct * total_demand, name="waste_limit")

obj = gp.LinExpr()

for p in products:
    for t in range(T):
        obj += cost_purchasing[p] * Q[p, t]

for p in products:
    SL = shelf_life[p]
    for l in locations:
        for t in range(T):
            for r in range(2, SL + 1):
                obj += cost_inventory[p] * (I[p, l, t, r] - sales[p, l, t, r])

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_waste[p] * W[p, l, t]

for p in products:
    for l in locations:
        for t in range(T):
            obj += cost_lost_sales[p] * lost[p, l, t]

m.setObjective(obj, GRB.MINIMIZE)

m.optimize()

print(f"status: {m.Status}")
if m.Status == 2:
    print(f"objective: {m.ObjVal}")
```

## STEP 1: UNDERSTAND THE PROBLEM

**Objective:** Minimize total cost consisting of:
- Purchasing costs
- Inventory holding costs
- Waste costs
- Lost sales costs

**Decisions to make:**
- Q[p,t]: Production/ordering quantity for product p in period t
- I[p,l,t,r]: Inventory of product p at location l at start of period t with r periods remaining
- sales[p,l,t,r]: Sales of product p at location l in period t from inventory with r periods remaining
- W[p,l,t]: Waste of product p at location l in period t
- lost_sales[p,l,t]: Lost sales (unmet demand)

**Constraints:**
1. Fresh inflow: New production enters with full shelf life
2. Aging dynamics: Inventory ages each period
3. Waste: Items with r=1 not sold become waste
4. Sales availability: Can only sell what's in inventory
5. FIFO selling: Sell oldest first
6. Demand satisfaction: Total sales + lost sales = demand
7. Cold storage capacity at each location
8. Production capacity limits
9. Global waste limit: Total waste ≤ 2% of total demand
10. Substitution: SKU_Basic can substitute for SKU_Premium

## STEP 2: FORMULATE THE MATHEMATICAL MODEL

**Sets:**
- P: Products {SKU_Basic, SKU_Premium, SKU_ShortLife}
- L: Locations {DC1, DC2, DC3, DC4, DC5}
- T: Periods {0, 1, ..., 19}
- R[p]: Remaining life values {1, 2, ..., shelf_life[p]}

**Parameters:**
- shelf_life[p]: Shelf life of product p
- demand_curve[p][t]: Total demand for product p in period t
- demand_share[l]: Fraction of demand at location l
- cold_capacity[l]: Cold storage capacity at location l
- cold_usage[p]: Cold storage units per item of product p
- production_cap[p][t]: Production capacity for product p in period t
- cost_purchasing[p], cost_inventory[p], cost_waste[p], cost_lost_sales[p]: Costs
- waste_limit_pct: Maximum waste as fraction of total demand (0.02)

**Decision Variables (all CONTINUOUS, non-negative):**
- Q[p,t] ≥ 0: Production quantity for product p in period t
- I[p,l,t,r] ≥ 0: Inventory at start of period t with r periods remaining
- sales[p,l,t,r] ≥ 0: Sales from inventory with r periods remaining
- W[p,l,t] ≥ 0: Waste
- lost_sales[p,l,t] ≥ 0: Lost sales
- sub[p_from, p_to, l, t] ≥ 0: Substitution quantity

**Constraints:**

1. Fresh inflow: I[p,l,t,SL[p]] = Q[p,t] * demand_share[l]

2. Aging: I[p,l,t+1,r] = I[p,l,t,r+1] - sales[p,l,t,r+1] for r=1..SL-1

3. Waste: W[p,l,t] = I[p,l,t,1] - sales[p,l,t,1]

4. Sales availability: sales[p,l,t,r] ≤ I[p,l,t,r]

5. FIFO: For r > 1: sales[p,l,t,r] ≤ I[p,l,t,r-1] - sales[p,l,t,r-1] (can only sell fresher if older is depleted)
   Actually, simpler: sum of sales from older ages must be maximized first - enforce via cost structure or explicit FIFO constraints

6. Demand satisfaction: sum_r(sales[p,l,t,r]) + sub_received[p,l,t] - sub_given[p,l,t] + lost_sales[p,l,t] = demand[p,l,t]

7. Cold capacity: sum_p sum_r (cold_usage[p] * I[p,l,t,r]) ≤ cold_capacity[l]

8. Production capacity: Q[p,t] ≤ production_cap[p][t]

9. Global waste limit: sum_{p,l,t} W[p,l,t] ≤ waste_limit_pct * sum_{p,t} demand_curve[p][t]

10. Initial inventory: I[p,l,0,r] = 0 for all r

**Objective:** Minimize sum of purchasing, holding, waste, and lost sales costs

